import AVFoundation
import WhisperKit

@MainActor
final class WhisperSpeechEngine: SpeechEngine {
    private(set) var transcript = "" { didSet { onTranscriptChange?(transcript) } }
    private(set) var isRecording = false { didSet { onRecordingChange?(isRecording) } }
    var onTranscriptChange: ((String) -> Void)?
    var onRecordingChange: ((Bool) -> Void)?

    private var whisperKit: WhisperKit?
    private var streamTranscriber: AudioStreamTranscriber?
    private let modelFolder: URL

    init(modelFolder: URL) {
        self.modelFolder = modelFolder
    }

    func start() {
        guard !isRecording else { return }
        transcript = ""

        Task {
            do {
                if whisperKit == nil {
                    print("[Whisper] loading model from \(modelFolder.path)")
                    let config = WhisperKitConfig(
                        model: modelFolder.lastPathComponent,
                        modelFolder: modelFolder.deletingLastPathComponent().path,
                        computeOptions: ModelComputeOptions(audioEncoderCompute: .cpuAndNeuralEngine, textDecoderCompute: .cpuAndNeuralEngine)
                    )
                    whisperKit = try await WhisperKit(config)
                    print("[Whisper] model loaded")
                }

                guard let kit = whisperKit,
                      let audioEncoder = kit.audioEncoder,
                      let featureExtractor = kit.featureExtractor,
                      let segmentSeeker = kit.segmentSeeker,
                      let textDecoder = kit.textDecoder,
                      let tokenizer = kit.tokenizer else {
                    print("[Whisper] model components not ready")
                    return
                }

                let session = AVAudioSession.sharedInstance()
                try session.setCategory(.playAndRecord, mode: .measurement, options: [.duckOthers, .defaultToSpeaker])
                try session.setActive(true, options: .notifyOthersOnDeactivation)

                let decodingOptions = DecodingOptions(
                    language: "en",
                    temperature: 0.0,
                    temperatureFallbackCount: 3,
                    sampleLength: 224,
                    usePrefillPrompt: true,
                    skipSpecialTokens: true
                )

                let transcriber = AudioStreamTranscriber(
                    audioEncoder: audioEncoder,
                    featureExtractor: featureExtractor,
                    segmentSeeker: segmentSeeker,
                    textDecoder: textDecoder,
                    tokenizer: tokenizer,
                    audioProcessor: kit.audioProcessor,
                    decodingOptions: decodingOptions
                ) { [weak self] oldState, newState in
                    Task { @MainActor [weak self] in
                        let confirmed = newState.confirmedSegments.map(\.text).joined(separator: " ")
                        let partial = newState.unconfirmedSegments.map(\.text).joined(separator: " ")
                        let full = [confirmed, partial].filter { !$0.isEmpty }.joined(separator: " ")
                        self?.transcript = full.trimmingCharacters(in: .whitespaces)
                    }
                }

                self.streamTranscriber = transcriber
                try await transcriber.startStreamTranscription()
                isRecording = true
                print("[Whisper] started recording")
            } catch {
                print("[Whisper] start failed: \(error.localizedDescription)")
                cleanupAudio()
            }
        }
    }

    func stop() -> String {
        print("[Whisper] stopping, transcript: \(transcript)")
        let result = transcript
        streamTranscriber?.stopStreamTranscription()
        cleanupAudio()
        return result
    }

    private func cleanupAudio() {
        streamTranscriber = nil
        isRecording = false
        transcript = ""

        try? AVAudioSession.sharedInstance().setCategory(.ambient)
        try? AVAudioSession.sharedInstance().setActive(true)
    }
}

