    @Published var transcript = ""
    @Published var isRecording = false
    @Published var engineType: SpeechEngineType {
        didSet { UserDefaults.standard.set(engineType.rawValue, forKey: "speechEngine") }
    }

    let modelManager = WhisperModelManager()
    private var activeEngine: SpeechEngine?

    init() {
        let stored = UserDefaults.standard.string(forKey: "speechEngine") ?? "apple"
        self.engineType = SpeechEngineType(rawValue: stored) ?? .apple
    }

    func requestPermissions() {
        SFSpeechRecognizer.requestAuthorization { status in
            print("[Speech] authorization: \(status.rawValue)")
        }
        AVAudioSession.sharedInstance().requestRecordPermission { granted in
            print("[Speech] microphone permission: \(granted)")
        }
    }

    func start() {
        guard !isRecording else { return }
        transcript = ""

        let engine: SpeechEngine
        if engineType == .whisper, let modelFolder = modelManager.downloadedModelFolder {
            engine = WhisperSpeechEngine(modelFolder: modelFolder)
        } else {
            if engineType == .whisper {
                print("[Speech] Whisper model not available, falling back to Apple Speech")
            }
            engine = AppleSpeechEngine()
        }

        engine.onTranscriptChange = { [weak self] text in
            self?.transcript = text
        }
        engine.onRecordingChange = { [weak self] recording in
            self?.isRecording = recording
        }

        activeEngine = engine
        engine.start()
    }

    func stop() -> String {
        print("[Speech] stopping, transcript: \(transcript)")
        guard let engine = activeEngine else { return transcript }
        let result = engine.stop()
        activeEngine = nil
        isRecording = false
        return result.isEmpty ? transcript : result
    }
}

