                    credentials = nil
                }
                Button("Cancel", role: .cancel) {}
            } message: {
                Text("You will need to scan the QR code again to reconnect.")
            }
        }
    }

    @ViewBuilder
    private var speechInputSection: some View {
        Section("Speech Input") {
            Picker("Engine", selection: Binding(
                get: { speechManager.engineType },
                set: { speechManager.engineType = $0 }
            )) {
                Text("Apple Speech").tag(SpeechEngineType.apple)
                Text("Whisper (Local)").tag(SpeechEngineType.whisper)
            }

            if speechManager.engineType == .whisper {
                Picker("Model", selection: Binding(
                    get: { speechManager.modelManager.selectedModel },
                    set: {
                        speechManager.modelManager.selectedModel = $0
                        speechManager.modelManager.checkExistingModel()
                    }
                )) {
                    ForEach(WhisperModelManager.availableModels, id: \.0) { name, size in
                        Text("\(name) (\(size))").tag(name)
                    }
                }

                switch speechManager.modelManager.downloadState {
                case .notDownloaded:
                    Button("Download Model") {
                        speechManager.modelManager.download()
                    }
                case .downloading(let progress):
                    VStack(alignment: .leading, spacing: 4) {
                        ProgressView(value: progress)
                        Text("Downloading... \(Int(progress * 100))%")
                            .font(.footnote)
                            .foregroundStyle(.secondary)
                    }
                case .downloaded:
                    HStack {
                        Label("Model Ready", systemImage: "checkmark.circle.fill")
                            .foregroundStyle(.green)
                        Spacer()
                        Button("Delete", role: .destructive) {
                            speechManager.modelManager.deleteModel()
                        }
                        .buttonStyle(.borderless)
                    }
                case .error(let message):
                    VStack(alignment: .leading, spacing: 4) {
                        Label("Download Failed", systemImage: "exclamationmark.triangle.fill")
                            .foregroundStyle(.red)
                        Text(message)
                            .font(.footnote)
                            .foregroundStyle(.secondary)
                        Button("Retry") {
                            speechManager.modelManager.download()
                        }
                    }
                }
            }

            Toggle("Auto-submit speech", isOn: $autoSubmitSpeech)
            Text("When enabled, automatically presses Enter after sending speech text.")
                .font(.footnote)
                .foregroundStyle(.secondary)
        }
    }
}

