import Foundation
import WhisperKit

enum WhisperDownloadState: Equatable {
    case notDownloaded
    case downloading(progress: Double)
    case downloaded
    case error(String)

    static func == (lhs: WhisperDownloadState, rhs: WhisperDownloadState) -> Bool {
        switch (lhs, rhs) {
        case (.notDownloaded, .notDownloaded), (.downloaded, .downloaded): return true
        case (.downloading(let a), .downloading(let b)): return a == b
        case (.error(let a), .error(let b)): return a == b
        default: return false
        }
    }
}

@MainActor
final class WhisperModelManager: ObservableObject {
    @Published var downloadState: WhisperDownloadState = .notDownloaded
    @Published var selectedModel: String {
        didSet { UserDefaults.standard.set(selectedModel, forKey: "whisperModel") }
    }

    static let availableModels = [
        ("tiny", "~65 MB"),
        ("tiny.en", "~65 MB"),
        ("base", "~130 MB"),
        ("base.en", "~130 MB"),
        ("small", "~450 MB"),
        ("small.en", "~450 MB"),
    ]

    private var modelsDirectory: URL {
        let appSupport = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first!
        return appSupport.appendingPathComponent("WhisperModels", isDirectory: true)
    }

    var downloadedModelFolder: URL? {
        let modelDir = modelsDirectory.appendingPathComponent(selectedModel, isDirectory: true)
        guard FileManager.default.fileExists(atPath: modelDir.path) else { return nil }
        return modelDir
    }

    var isModelAvailable: Bool {
        downloadedModelFolder != nil
    }

    init() {
        self.selectedModel = UserDefaults.standard.string(forKey: "whisperModel") ?? "tiny.en"
        checkExistingModel()
    }

    func checkExistingModel() {
        downloadState = isModelAvailable ? .downloaded : .notDownloaded
    }

    func download() {
        guard downloadState != .downloaded else { return }
        downloadState = .downloading(progress: 0)

        Task {
            do {
                try FileManager.default.createDirectory(at: modelsDirectory, withIntermediateDirectories: true)

                print("[WhisperModel] downloading model: \(selectedModel)")
                let folder = try await WhisperKit.download(
                    variant: "openai_whisper-\(selectedModel)",
                    progressCallback: { [weak self] progress in
                        Task { @MainActor [weak self] in
                            self?.downloadState = .downloading(progress: progress.fractionCompleted)
                        }
                    }
                )
                print("[WhisperModel] downloaded to: \(folder)")

                // Move to our managed directory
                let dest = modelsDirectory.appendingPathComponent(selectedModel, isDirectory: true)
                if FileManager.default.fileExists(atPath: dest.path) {
                    try FileManager.default.removeItem(at: dest)
                }
                try FileManager.default.copyItem(at: folder, to: dest)

                downloadState = .downloaded
                print("[WhisperModel] model ready at: \(dest.path)")
            } catch {
                print("[WhisperModel] download failed: \(error.localizedDescription)")
                downloadState = .error(error.localizedDescription)
            }
        }
    }

    func deleteModel() {
        guard let folder = downloadedModelFolder else { return }
        do {
            try FileManager.default.removeItem(at: folder)
            downloadState = .notDownloaded
            print("[WhisperModel] model deleted")
        } catch {
            print("[WhisperModel] delete failed: \(error.localizedDescription)")
        }
    }
}

